import type { TroubleCodeGuide } from "./trouble-code-data";
import { make } from "./trouble-code-grand-cherokee-ram";

const owners={label:"Subaru owner manuals and vehicle resources",url:"https://www.subaru.com/owners/vehicle-resources.html",note:"Official model-year operating, warning, fuel and maintenance information"};
const stis={label:"Subaru Technical Information System (STIS)",url:"https://techinfo.subaru.com/",note:"Current VIN-, engine- and model-year-specific service-manual diagnostic procedures"};
const camBulletin={label:"Subaru Bulletin 02-132-12R — intake oil-control DTC diagnosis",url:"https://static.nhtsa.gov/odi/tsbs/2015/SB-10080600-0699.pdf",note:"Model-specific P0011/P0021 route, SSM data and controlled oil-control-valve comparison; one-time seals and exact applicability matter"};
const catalystBulletin={label:"Subaru Bulletin 09-110-23R — P0420 diagnostic procedure",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10246083-0001.pdf",note:"Covers listed Outback and Forester years and requires companion-code, mixture, misfire, sensor and exhaust checks before catalyst judgment"};
const rearSensorBulletin={label:"Subaru Bulletin 09-115-24 — rear oxygen-sensor identification",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11000828-0001.pdf",note:"Covers identified late-model Outback and Forester applications with P0137/P0138/P0140/P0141; requires the published sensor-identification procedure"};
const foresterTurboBulletin={label:"Subaru Bulletin 11-169-16R — 2014–2017 Forester turbo ECM",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10155221-9999.pdf",note:"Narrow FA20 turbo reprogramming branch that includes P0137; fuel quality and exact ECM applicability must be checked first"};
const p2096Bulletin={label:"Subaru Bulletin 18-228-25 — P2096/P2097 service-manual correction",url:"https://static.nhtsa.gov/odi/tsbs/2025/MC-11025790-0001.pdf",note:"Replaces specified diagnostic steps for listed 2015–2025 Outback and 2019–2025 Forester applications; it is not an automatic sensor or catalyst replacement instruction"};
const techTips={label:"Subaru TechTIPS article locator — emission-system diagnostics",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10160508-9999.pdf",note:"Indexes Subaru factory diagnostic articles for P0457, P0171 and related emission-system testing; use the current STIS procedure for the exact vehicle"};

const outback={name:"Subaru Outback",kicker:"SUBARU OUTBACK · BOXER ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Subaru Outback",about:"Subaru Outback engine and emissions diagnostics",yearsIntro:"Outback diagnostics span Legacy-based early models through modern crossovers with EJ25, EZ30/EZ36, FB25 and FA24 turbo engines. Valve-lift hardware, AVCS strategy, fuel injection, bank layout, rear oxygen sensors, catalysts and EVAP leak detection changed repeatedly. Confirm VIN, model year, engine code, aspiration, emissions label and current ECM calibration before applying a code definition, bank location or bulletin."};
const forester={name:"Subaru Forester",kicker:"SUBARU FORESTER · BOXER ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Subaru Forester",about:"Subaru Forester engine and emissions diagnostics",yearsIntro:"Forester diagnostics span SF through SK generations with EJ-series SOHC and turbo engines, FB25 and FA20 direct-injection turbo applications. AVLS and AVCS are different systems, bank orientation matters, and catalyst, EVAP and oxygen-sensor hardware changes by year and engine. Confirm VIN, model year, engine code, turbo status, emissions label and current ECM calibration before using any test or bulletin."};

export const troubleCodeOutback:TroubleCodeGuide[]=[
 make(outback,{code:"P0420",slug:"subaru/outback/p0420",title:"P0420 Code Subaru Outback: Catalyst Test Before Replacement",description:"Diagnose Outback P0420 with Subaru's companion-code, exhaust-leak, A/F sensor, rear-O2 and catalyst procedure by engine and year.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means the Outback ECM calculated that the Bank 1 catalyst stored less oxygen than expected; it does not prove the converter alone failed. Subaru bulletin 09-110-23R covers specified 2017–2019 Outback 2.5L and 2020–2023 Outback applications and explicitly screens P0300-series misfires, P0171/P0172 mixture faults and P0137-series rear-sensor faults before catalyst judgment. Inspect exhaust leakage and oil consumption, graph upstream A/F and downstream O2 response, and use the VIN-correct STIS test.",yearNotes:["09-110-23R covers listed years, not every Outback ever built.","Four-cylinder and six-cylinder exhaust layouts and bank definitions differ.","Oil consumption, misfire and rich operation can damage a healthy replacement catalyst.","A flashing MIL requires reducing load immediately."],deepDive:[{heading:"Subaru's bulletin makes prerequisite codes part of the catalyst test",paragraphs:["Save confirmed, pending and permanent codes before clearing. Bulletin 09-110-23R specifically names misfire, fuel-system and rear-oxygen-sensor codes because catalyst-monitor data cannot be trusted while combustion or feedback is wrong.","Repair an active P0300, P0171, P0172 or P0137 branch first. The converter may still be damaged, but testing it before the upstream fault is controlled can produce an expensive repeat repair."]},{heading:"Inspect a cold exhaust and the engine's oil history",paragraphs:["Check manifold joints, front-pipe flanges, welds and sensor bungs for a cold tick, soot or looseness. Outside oxygen entering the exhaust can change the signals used to calculate storage efficiency.","Review oil additions, plug deposits, coolant loss and prior misfire. Ash, raw fuel and coolant contamination can reduce converter capacity, while a broken substrate may rattle or restrict high-load breathing."]},{heading:"Sensor shapes are evidence, not a parts order",paragraphs:["Graph the upstream A/F sensor and rear O2 sensor only after full warm-up and the exact monitor prerequisites. A rear trace resembling upstream activity supports reduced storage but does not identify whether the converter, a leak or abnormal combustion caused it.","Verification requires completion of the catalyst monitor with no pending P0420. Clearing memory and seeing the lamp remain off for a short trip only resets the test; it does not demonstrate a repair."]}],sources:[catalystBulletin,stis,owners]}),
 make(outback,{code:"P0171",slug:"subaru/outback/p0171",title:"P0171 Code Subaru Outback: Lean Bank 1 Diagnosis",description:"Diagnose Outback P0171 using idle/load fuel correction, intake smoke, purge, MAF, A/F sensor and fuel-delivery evidence.",definition:"System Too Lean (Bank 1)",kind:"lean",quickAnswer:"P0171 means the Outback ECM reached excessive positive fuel correction on Bank 1. Preserve short-term correction and A/F learning at warm idle, raised rpm and controlled load. Correction strongest at idle favors an intake, PCV, brake-booster or purge leak; correction that worsens with load favors measured-air error or fuel delivery. On a six-cylinder, compare the other bank. Do not replace the upstream A/F sensor until intake sealing, exhaust integrity, airflow plausibility and fuel pressure are tested.",yearNotes:["EJ, EZ, FB and FA engines use different airflow and fuel systems.","Turbo models require inspection of both vacuum and pressurized intake paths.","Six-cylinder Outbacks permit bank comparison; four-cylinder bank language still follows the boxer layout.","Direct-injection FA24 testing requires high-pressure fuel safety."],deepDive:[{heading:"The shape of fuel correction directs the first test",paragraphs:["Record correction at hot idle, approximately 2,500 rpm without load and a safe road load. A vacuum leak contributes a larger percentage of air at idle, while a restricted pump or under-reporting MAF often becomes clearer as airflow demand rises.","Compare Bank 1 and Bank 2 on an EZ six-cylinder under the same condition. One-bank correction favors a local manifold, injector, exhaust or sensor problem; both banks favor shared intake, purge, MAF or fuel supply."]},{heading:"Smoke the intake rather than spraying chemicals",paragraphs:["Inspect the air-box seal, flexible boot underside, PCV plumbing, brake-booster connection and manifold seals. Turbo models also need an approved pressure or smoke test of intercooler and charge connections where applicable.","Command purge off and verify that the valve truly seals. Excess flow can create idle lean correction, while a purge fault after refueling may also produce hard starting or an EVAP companion code."]},{heading:"Validate airflow, pressure and sensor response",paragraphs:["Compare MAF, calculated load and A/F sensor response with engine-specific known-good data. Check for exhaust leakage ahead of the upstream sensor before interpreting oxygen feedback as a failed sensor.","Use the correct low- or high-pressure fuel procedure for the engine and verify injector contribution. Final proof is stable correction near target under the original condition with no pending P0171."]}],sources:[techTips,stis,owners]}),
 make(outback,{code:"P0300",slug:"subaru/outback/p0300",title:"P0300 Code Subaru Outback: Boxer Misfire Pattern Diagnosis",description:"Diagnose Outback P0300 with Subaru cylinder counts, bank trims, plugs, coils, injectors, compression and cam-timing evidence.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple cylinders misfired or no single cylinder dominated the Outback's detection threshold. Save P0301–P0306 companions, roughness counts, fuel corrections, temperature and load before moving components. A single leader calls for plug, ignition, injector and compression tests; one boxer bank raises local intake, exhaust and cam-control causes; all cylinders raise shared airflow, fuel, voltage or contamination. A flashing MIL means catalyst-damaging active misfire and requires reducing load immediately.",yearNotes:["Cylinder numbering differs from the physical left-to-right assumptions many generic diagrams use.","EJ coil-pack, coil-on-plug FB/FA and six-cylinder ignition systems require different tests.","Cold-start-only counts can disappear quickly as the engine warms.","P0011/P0021 companions move oil control and cam timing higher."],deepDive:[{heading:"Capture Subaru roughness data before moving a coil",paragraphs:["Use SSM-capable data to record which cylinders accumulate counts at cold start, idle and the freeze-frame load. Label plugs and ignition parts; move only one known-good component when a controlled swap is appropriate.","If several cylinders on one boxer bank lead, align that pattern with fuel correction, exhaust leaks and AVCS data. Random does not mean every ignition coil should be replaced."]},{heading:"Plug deposits preserve the story",paragraphs:["Compare gap, fuel wetness, oil ash, carbon and an unusually steam-cleaned insulator across labeled cylinders. Those patterns separate weak spark from leaking fuel, oil entry or coolant exposure.","When the count stays after a valid ignition test, measure injector contribution and cylinder sealing. Compression and leak-down should be interpreted with the engine's valve timing and temperature."]},{heading:"Shared patterns need system-level tests",paragraphs:["All-cylinder counts after refueling raise fuel quality; load-only breakup raises ignition reserve and delivery; cold-only misfire raises sealing, mixture and deposit questions. Check charging voltage and grounds when events span both banks.","Verify in the original safe condition while monitoring counters. Do not deliberately sustain a flashing MIL to reproduce the fault, and do not judge the catalyst until misfire is controlled."]}],sources:[catalystBulletin,stis,owners]}),
 make(outback,{code:"P0028",slug:"subaru/outback/p0028",title:"P0028 Code Subaru Outback: Bank 2 AVLS Oil-Control Test",description:"Diagnose applicable Outback P0028 as a Bank 2 intake valve-lift oil-control fault—not an AVCS cam-timing code.",definition:"Intake Valve Control Solenoid Circuit Range/Performance (Bank 2)",kind:"subaruAvls",quickAnswer:"On an applicable older Outback with Subaru's Active Valve Lift System, P0028 concerns Bank 2 intake valve-control range/performance. The ECM expects the AVLS oil-pressure switch to agree when the switching solenoid redirects oil to the rocker mechanism. Verify the exact engine actually has AVLS, then check oil level, viscosity, filter and pressure; save switch/command data; load-test the Bank 2 switch, solenoid and harness; and compare operation with Bank 1. Do not use a P0021 AVCS cam-timing repair for this code.",yearNotes:["P0028 is relevant to applicable AVLS-equipped EJ25 SOHC configurations, not every Outback engine.","AVLS changes valve lift; AVCS changes cam phase.","Bank 2/left-hand orientation must be confirmed with VIN-correct Subaru service information.","Oil-pressure warnings or valvetrain noise require stopping operation."],deepDive:[{heading:"First prove the vehicle has the system named by the code",paragraphs:["Outback generations include EJ, FB, FA and EZ engines with different valve-control hardware. Decode the VIN and read the emissions/service data before searching for a Bank 2 AVLS pressure switch that a later engine may not contain.","Generic scanners sometimes shorten P0028 to a vague solenoid description. Subaru's applicable test evaluates the relationship among ECM command, oil pressure, switching valve and pressure-switch feedback."]},{heading:"Electrical agreement and hydraulic action are separate questions",paragraphs:["Load-test power, control, ground and terminal grip at the switching solenoid and pressure switch. A resistance reading through a weak connection does not demonstrate that the circuit carries current when hot.","If the electrical path passes, verify oil pressure and passage flow under the specified enable condition. Wrong viscosity, low level, sludge or a restricted gallery can prevent the switch from changing even when the solenoid clicks."]},{heading:"Mechanical lift comes last, not first",paragraphs:["Compare Bank 1 and Bank 2 switching data at the same oil temperature and rpm. Correct command with incorrect pressure feedback narrows the switch, oil supply or mechanical AVLS path.","Inspect rocker and lift hardware only after electrical and hydraulic evidence supports it. Verification is correct Bank 2 state change at the original condition and no pending P0028."]}],sources:[stis,owners]}),
 make(outback,{code:"P0011",slug:"subaru/outback/p0011",title:"P0011 Code Subaru Outback: Right-Bank AVCS Diagnosis",description:"Diagnose Outback P0011 using Subaru SSM desired/actual timing, oil checks, right-bank control-valve testing and correlation data.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 1)",kind:"subaruVvt",quickAnswer:"P0011 means the applicable Outback's Bank 1 intake cam stayed more advanced than commanded or failed its AVCS performance test. For the FB applications addressed by Subaru bulletin 02-132-12R, P0011 identifies the right-hand intake system. Save SSM desired/actual angle, verify oil and pressure, test the oil-control valve and circuit, and scope cam/crank correlation before mechanical work. The bulletin's side-to-side valve test has strict intake-to-intake rules and requires new one-time seals.",yearNotes:["02-132-12R has model-, engine- and year-specific applicability and verification routes.","Right/left is vehicle orientation; confirm the service-manual convention.","Never swap an intake oil-control valve with an exhaust valve.","A stable phase error differs from an intermittent sensor dropout."],deepDive:[{heading:"Use Subaru's bank-specific SSM evidence",paragraphs:["Record requested and actual right-bank intake angle at idle, during a controlled command and at the freeze-frame temperature. Compare the opposite bank only under the same oil temperature and rpm.","P0011 with P0021 suggests a shared oil, voltage or mechanical timing issue more strongly than two simultaneous valve failures. A single-bank result makes the local valve, passage, phaser and feedback path more useful."]},{heading:"The bulletin's valve swap is controlled, not casual",paragraphs:["On covered applications Subaru permits intake-to-intake or exhaust-to-exhaust comparison, never intake with exhaust on the same side. It also specifies replacement of the O-ring and nylon backer ring because those seals are one-time use.","If the code follows a correctly performed comparison, the valve becomes supported by evidence. If it stays on the right bank, continue with circuit, oil-passage, phaser and timing diagnosis rather than replacing the other valve."]},{heading:"Scope feedback before opening the timing drive",paragraphs:["Missing or noisy cam edges favor a sensor, connector or harness fault; a repeatable phase offset with clean signals favors hydraulic or mechanical timing. Startup rattle adds weight but is not proof by itself.","After repair, use the exact model's bulletin drive-cycle or inspection-mode procedure. Desired and actual timing must track and P0011 must remain absent as pending—not merely cleared."]}],sources:[camBulletin,stis,owners]}),
 make(outback,{code:"P0021",slug:"subaru/outback/p0021",title:"P0021 Code Subaru Outback: Left-Bank AVCS Diagnosis",description:"Diagnose Outback P0021 with left-bank AVCS oil-control, desired/actual cam angle and Subaru's controlled comparison procedure.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 2)",kind:"subaruVvt",quickAnswer:"P0021 means the applicable Outback's Bank 2 intake cam was more advanced than commanded or failed its timing-control performance check. In Subaru's covered FB procedure, P0021 points to the left-hand intake oil-control system. Verify oil level, grade, filter and pressure; preserve both-bank desired/actual angles; test the left valve and circuit; then distinguish signal dropout from a stable mechanical phase error. P0028 is an AVLS valve-lift code and must not be substituted for this AVCS diagnosis.",yearNotes:["P0021 is the Bank 2/left-hand intake branch on the covered Subaru FB engine.","Six-cylinder and other engine families require their own STIS definition.","Low oil or a restricted passage can mimic a failed valve.","The bulletin requires new one-time valve seals during its comparison procedure."],deepDive:[{heading:"Compare equal banks under equal conditions",paragraphs:["Save left and right intake requested/actual angle at the same oil temperature, rpm and load. A left-only response error localizes diagnosis more effectively than an isolated resistance check.","When both banks are abnormal, inspect oil supply, charging voltage, common grounds and base timing before ordering two oil-control valves."]},{heading:"A click does not prove oil-control performance",paragraphs:["Command the left valve with SSM and test current, wiring and terminal fit. Then verify the cam actually moves and returns; a clicking coil may coexist with a restricted passage or sticking hydraulic spool.","Follow Subaru's controlled comparison rules only when the exact bulletin applies. Replace its O-ring and backer ring, and do not interchange intake and exhaust valves."]},{heading:"Use waveform behavior to choose repair depth",paragraphs:["Intermittent signal loss, noise or implausible amplitude favors sensor or harness testing. Clean, repeatable signals with a phase offset and timing noise move phaser, chain and mechanical indexing higher.","Complete the exact Outback verification route after repair. Correct left-bank tracking and no pending P0021 are stronger proof than an extinguished lamp immediately after clearing."]}],sources:[camBulletin,stis,owners]}),
 make(outback,{code:"P0457",slug:"subaru/outback/p0457",title:"P0457 Code Subaru Outback: Fuel Cap and EVAP Leak Diagnosis",description:"Diagnose Outback P0457 by preserving cap condition, testing purge and vent sealing, and locating the EVAP leak with safe pressure.",definition:"EVAP System Leak Detected (Fuel Cap Loose/Off)",kind:"evapCap",quickAnswer:"P0457 indicates the Outback EVAP monitor found an open or significant leak commonly associated with a loose or missing fuel cap, but the code does not prove the cap is the only cause. Record the cap and fuel level before tightening anything. Inspect the cap seal and filler neck, test purge and vent operation, then use regulated EVAP smoke to inspect hoses, canister, tank and pump-module seals. A new cap without a confirmed sealing fault is not a complete diagnosis.",yearNotes:["Cap design, leak-check hardware and canister location vary by generation.","Salt corrosion at the filler neck matters on older vehicles.","Recent fuel-pump, tank, collision or rear-underbody work changes inspection priority.","Fuel level and overnight soak often gate monitor completion."],deepDive:[{heading:"The found cap condition is diagnostic evidence",paragraphs:["Photograph whether the cap is absent, cross-threaded, insufficiently tightened or visibly damaged before changing it. Inspect the sealing ring and the filler-neck surface for rust, dents and contamination.","If the cap was loose and the system then passes an approved leak check, that supports the cause. If P0457 returns, do not keep buying caps; test the complete system."]},{heading:"Purge and vent valves must seal, not merely click",paragraphs:["A purge valve that passes manifold vacuum when commanded closed can prevent the monitor from holding pressure and may cause hard starting after refueling. Check its actual flow or sealing behavior.","Command the vent/leak-check system according to STIS and use only regulated EVAP pressure. Sectioning filler, canister and tank branches makes a small smoke plume easier to locate."]},{heading:"Verification depends on monitor conditions",paragraphs:["Record fuel level, ambient temperature and soak time because the EVAP test will not run under every condition. Do not overfill the tank trying to force readiness.","After the proven leak is repaired, complete the monitor and check pending and permanent status. A cleared lamp before readiness is incomplete evidence."]}],sources:[techTips,stis,owners]}),
 make(outback,{code:"P0172",slug:"subaru/outback/p0172",title:"P0172 Code Subaru Outback: Rich Bank 1 Fuel Diagnosis",description:"Diagnose Outback P0172 with bank fuel learning, purge, injector, pressure, MAF, A/F sensor and oil-dilution checks.",definition:"System Too Rich (Bank 1)",kind:"rich",quickAnswer:"P0172 means the Outback ECM removed more fuel than its allowed Bank 1 correction because feedback appeared rich. Save A/F correction and learning at idle and load before resetting. Test for a leaking injector, excessive fuel pressure, purge flow at the wrong time, biased MAF or A/F data, intake restriction and misfire. Compare banks on an EZ six-cylinder. If the oil level has risen or smells strongly of gasoline, limit running until fuel dilution is addressed.",yearNotes:["Port-injected EJ/EZ/FB and direct-injected FA systems require different pressure tests.","A one-bank rich pattern on a six-cylinder favors local causes.","Cold-start enrichment and purge command must be considered when interpreting data.","Fuel dilution threatens lubrication and catalyst life."],deepDive:[{heading:"Record where the ECM removes fuel",paragraphs:["Compare short-term correction and learned values at warm idle, raised rpm and controlled load. Rich correction strongest at idle favors injector leakage or purge flow; correction across the range raises pressure, airflow bias or shared sensing.","On a six-cylinder, compare Bank 1 with Bank 2. One wet plug or one-bank correction is more specific than replacing a shared MAF sensor."]},{heading:"Prove excess fuel before blaming oxygen feedback",paragraphs:["Check residual pressure and injector contribution with the engine-specific safe procedure. Direct-injection lines and rails retain hazardous pressure and should not be opened with generic methods.","Isolate purge flow and inspect plugs while keeping them labeled. A failed combustion event can leave oxygen and fuel in the exhaust, so misfire data must be reconciled with the reported rich correction."]},{heading:"Validate measured air and protect the oil",paragraphs:["Inspect the filter, intake duct and MAF plausibility, then test the upstream A/F sensor response and pre-sensor exhaust integrity. A rich code describes correction, not a guaranteed sensor fault.","If fuel dilution is confirmed, repair its cause and follow the proper oil-and-filter service. Verify normal learning under the original condition with no pending P0172."]}],sources:[techTips,stis,owners]}),
 make(outback,{code:"P0137",slug:"subaru/outback/p0137",title:"P0137 Code Subaru Outback: Rear O2 Low-Voltage Diagnosis",description:"Diagnose Outback P0137 with rear-sensor identification, exhaust-leak, heater, harness and mixture tests before replacement.",definition:"O2 Sensor Circuit Low Voltage (Bank 1, Sensor 2)",kind:"rearO2Low",quickAnswer:"P0137 means the Bank 1 downstream oxygen-sensor signal stayed lower than expected. Confirm the rear sensor rather than the upstream A/F sensor, inspect the exhaust for air entry, graph fuel correction and both sensor signals, and load-test the signal, ground, heater and harness. Subaru bulletin 09-115-24 covers identified late-model Outback applications and requires a sensor-identification procedure; it does not authorize replacement on every year. Earlier calibration listings are also application-specific.",yearNotes:["09-115-24 includes 2020–2024 Outback 2.5L applications with identification boundaries.","Six-cylinder and turbo exhaust packaging may differ.","P0171, P0300 or P0420 companions must be interpreted before a sensor verdict.","Rear O2 and upstream A/F sensors are not interchangeable."],deepDive:[{heading:"Low voltage can be real oxygen or an electrical fault",paragraphs:["Graph Bank 1 Sensor 2 after warm-up while recording upstream correction. A signal pinned near zero with a failed circuit test differs from a responsive sensor reporting a real lean exhaust stream.","Load-test heater supply, signal return, ground and terminal tension. Exhaust heat, water and prior repair can damage routing even when static continuity looks acceptable."]},{heading:"Inspect the exhaust before replacing the sensor",paragraphs:["Check joints, welds, flex sections and the sensor bung cold for soot or a tick. Outside air entering ahead of the sensor can hold the reported voltage low.","Resolve P0171 or active misfire because those conditions change exhaust oxygen. If P0420 is present, Subaru's catalyst bulletin lists rear-sensor and mixture faults among prerequisites."]},{heading:"Apply the production change by identification, not keyword",paragraphs:["Bulletin 09-115-24 describes an optimized rear-sensor design and a required identification process for listed applications. Model name and P0137 alone do not establish that the vehicle has the superseded sensor.","After the proven circuit, leak, mixture or sensor fault is repaired, complete the hot monitor and confirm plausible rear-sensor response with no pending P0137."]}],sources:[rearSensorBulletin,catalystBulletin,stis,owners]}),
 make(outback,{code:"P2096",slug:"subaru/outback/p2096",title:"P2096 Code Subaru Outback: Post-Catalyst Lean Diagnosis",description:"Diagnose Outback P2096 using Subaru's corrected procedure, upstream trims, exhaust leaks, rear O2 response and catalyst prerequisites.",definition:"Post Catalyst Fuel Trim System Too Lean (Bank 1)",kind:"postCatLean",quickAnswer:"P2096 means the Outback's post-catalyst Bank 1 correction reached its lean limit; it does not automatically identify a rear oxygen sensor or catalyst. Save P0171, P0300, P0137 and P0420 companions plus upstream trims and rear-sensor data. Inspect exhaust leakage, resolve upstream mixture and misfire, then test the rear sensor and catalyst. Subaru bulletin 18-228-25 replaces specific diagnostic steps for listed 2015–2025 Outback 2.5L and 2020–2025 Outback XT applications.",yearNotes:["18-228-25 is a service-manual correction, not an automatic replacement campaign.","Its covered diagnostic steps differ for 2.5L and XT 2.4L applications.","Older Outbacks require the STIS procedure for their year and engine.","P2096 with P0171 changes priority toward an upstream lean cause."],deepDive:[{heading:"Start upstream even though the code says post catalyst",paragraphs:["Review fuel correction, misfire counts and upstream A/F response first. A true lean mixture continues through the catalyst and can make rear-sensor interpretation misleading.","P0171 across both boxer banks suggests shared intake, MAF, purge or fuel delivery. A bank-local result suggests a local exhaust leak, injector, manifold or feedback issue."]},{heading:"Small exhaust leaks can imitate lean correction",paragraphs:["Inspect cold for soot and leakage at manifolds, flanges, welds, flex sections and sensor bungs. Use an approved low-pressure test when the leak is too small to hear.","Then test Bank 1 Sensor 2 circuitry and response. Replacing it because the code contains post-catalyst skips the distinction between real oxygen and biased voltage."]},{heading:"Use the corrected late-model steps exactly",paragraphs:["Bulletin 18-228-25 identifies which numbered STIS steps are replaced for covered Outback engines. That boundary matters: it updates diagnosis and does not state that every P2096 needs a sensor, ECM or converter.","Verify normal upstream and post-catalyst data through the required monitor, with no pending P2096. Address P0420 only after mixture, misfire, leaks and sensors pass."]}],sources:[p2096Bulletin,rearSensorBulletin,catalystBulletin,stis,owners]})
];

export const troubleCodeForester:TroubleCodeGuide[]=[
 make(forester,{code:"P0420",slug:"subaru/forester/p0420",title:"P0420 Code Subaru Forester: Converter Diagnosis by Engine",description:"Diagnose Forester P0420 with Subaru's prerequisite-code, exhaust, sensor and catalyst tests for naturally aspirated or turbo engines.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means the Forester ECM calculated insufficient oxygen-storage performance in the Bank 1 catalyst. Subaru bulletin 09-110-23R covers specified 2017–2018 Forester 2.5L and 2019–2023 Forester models and directs technicians to address misfire, mixture and oxygen-sensor codes before judging the converter. Inspect exhaust leakage, oil consumption and prior turbo or fueling faults, then graph the correct upstream A/F and downstream O2 sensors under monitor conditions. A similar-looking trace alone is not a converter diagnosis.",yearNotes:["09-110-23R covers listed model years; older EJ and turbo Foresters need their own procedure.","Turbo exhaust leaks and oil consumption can affect catalyst evidence.","P0137 and P0171/P0172 are prerequisites in Subaru's published P0420 path.","A flashing MIL indicates active catalyst-damaging misfire."],deepDive:[{heading:"Forester engine family changes the evidence",paragraphs:["An EJ25 SOHC, EJ255 turbo, FB25 and FA20DIT do not share identical exhaust, fueling or sensor layouts. Identify engine and emissions label before selecting Bank 1 sensors or a converter assembly.","On a turbo engine, inspect pre-turbine and post-turbine joints as applicable and review oil entry through engine or turbo systems. A converter can be damaged by the condition that came before P0420."]},{heading:"Follow Subaru's prerequisite screen",paragraphs:["Save confirmed, pending and permanent codes. Bulletin 09-110-23R specifically checks P0300-series, P0171/P0172 and rear-sensor faults because misfire, mixture and feedback must be reliable first.","Inspect a cold exhaust for soot and leakage. Resolve abnormal fuel correction and oil/coolant consumption before interpreting sensor activity or installing a converter."]},{heading:"Complete the monitor after the root cause is controlled",paragraphs:["Graph sensors at full temperature and stable load specified for the engine. Rear activity that resembles upstream supports reduced storage but does not reveal whether leakage, contamination or the substrate caused it.","Verification is a completed catalyst monitor without pending P0420. A recently cleared lamp and incomplete readiness do not demonstrate success."]}],sources:[catalystBulletin,stis,owners]}),
 make(forester,{code:"P0171",slug:"subaru/forester/p0171",title:"P0171 Code Subaru Forester: Lean Correction by Turbo or NA",description:"Diagnose Forester P0171 with fuel-learning patterns, smoke/pressure tests, purge, MAF, A/F sensor and fuel delivery.",definition:"System Too Lean (Bank 1)",kind:"lean",quickAnswer:"P0171 means the Forester ECM added excessive Bank 1 fuel correction. Record correction and learning at warm idle and load before clearing. On a naturally aspirated engine, idle-heavy correction points toward intake, PCV, booster or purge leakage; worsening under load raises MAF and fuel supply. Turbo Foresters need both vacuum-leak and charge-path testing because a hose may behave differently under boost. Confirm exhaust integrity and upstream A/F response before replacing the sensor.",yearNotes:["EJ25, EJ255, FB25 and FA20DIT intake and fuel systems differ.","FA20DIT high-pressure fuel work requires the factory safety process.","Turbo inlet, intercooler and bypass/control plumbing add leak paths.","Subaru TechTIPS indexes model-specific P0171 diagnostic guidance; current STIS controls."],deepDive:[{heading:"Map fuel correction against operating state",paragraphs:["Record learned and immediate correction at idle, raised rpm and a safe loaded condition. If correction falls as airflow rises, unmetered vacuum air is more likely; if it grows, delivery or measured-air error deserves priority.","Turbo data needs manifold pressure and commanded boost context. A pre-turbo inlet split may draw unmetered air, while a charge leak can appear primarily under boost."]},{heading:"Test the whole air path",paragraphs:["Inspect the flexible inlet, PCV hoses, manifold gaskets and brake-booster line, then smoke-test with the engine off. Turbo models need an approved low-pressure charge-system test rather than excessive shop pressure.","Isolate purge and watch correction. The valve must seal when commanded closed; a click is not proof, and refueling complaints provide useful context."]},{heading:"Separate fuel supply from A/F feedback",paragraphs:["Validate MAF and calculated load, check for exhaust leakage ahead of the A/F sensor, and test fuel pressure and injector contribution by the exact engine procedure.","Do not open FA20DIT high-pressure hardware without depressurization and training. Verify normal learning under the original condition with no pending P0171."]}],sources:[techTips,stis,owners]}),
 make(forester,{code:"P0300",slug:"subaru/forester/p0300",title:"P0300 Code Subaru Forester: Random Misfire by Boxer Bank",description:"Diagnose Forester P0300 using cold/load roughness counts, bank patterns, plugs, ignition, injectors, compression and timing.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple Forester cylinders misfired or the ECM found no single dominant cylinder. Preserve roughness counts, P0301–P0304 companions, temperature, load, fuel correction and AVCS data. Cold-only, load-only, one-cylinder, one-bank and all-cylinder patterns point to different tests. EJ coil-pack, FB coil-on-plug and FA20DIT systems are not interchangeable. Stop sustained operation when the MIL flashes because raw fuel can rapidly overheat the close-coupled catalyst.",yearNotes:["Forester boxer cylinder numbering must come from the exact engine diagram.","EJ and FB/FA ignition, injector and valve systems differ.","Turbo load can expose ignition reserve or fuel-pressure weakness.","P0011/P0021 or P0340 companions raise timing and feedback priority."],deepDive:[{heading:"Preserve the pattern before parts disturb it",paragraphs:["Capture counts immediately after a cold start and at the freeze-frame condition. Label plugs and coils and perform one controlled comparison rather than shuffling a complete set.","One bank of cylinders raises shared intake, exhaust, injector supply or AVCS questions. All-cylinder events raise MAF, fuel pressure, charging voltage, purge flow or contaminated fuel."]},{heading:"Use plug evidence with mechanical tests",paragraphs:["Compare gap, cracking, fuel wetness, oil ash and unusual cleaning while every plug remains tied to its cylinder. Replacing all plugs before recording them erases useful evidence.","If the misfire does not follow a valid ignition test, check injector contribution, compression and leak-down. Valve sealing, rocker damage or timing error can imitate ignition failure."]},{heading:"Reproduce safely, especially on turbo models",paragraphs:["A boost-only breakup should be tested with ignition reserve, fuel pressure and charge-leak data, not repeated full-throttle runs with a flashing lamp. Stop for severe shaking or mechanical noise.","Final proof is stable roughness counts in the original safe condition and no pending P0300. Catalyst testing follows only after combustion remains controlled."]}],sources:[catalystBulletin,stis,owners]}),
 make(forester,{code:"P0028",slug:"subaru/forester/p0028",title:"P0028 Code Subaru Forester: Left-Bank AVLS Diagnosis",description:"Diagnose applicable Forester P0028 through Bank 2 AVLS switch, solenoid, oil pressure, circuit and valve-lift tests.",definition:"Intake Valve Control Solenoid Circuit Range/Performance (Bank 2)",kind:"subaruAvls",quickAnswer:"On an applicable AVLS-equipped Forester, P0028 means Bank 2 intake valve-control feedback did not match the commanded lift state. Confirm the EJ engine and system first: later FB25 and FA20 engines use different valve-control strategies. Verify oil level, grade, filter and pressure, save AVLS switch and command data, load-test the Bank 2 pressure switch, switching solenoid and wiring, then compare banks. P0028 AVLS valve lift is not the same fault as P0021 AVCS cam timing.",yearNotes:["Applicable older EJ25 SOHC AVLS Foresters use oil-controlled valve-lift switching.","Later FB and turbo FA engines require their own code definition and hardware map.","Bank 2 is the applicable left-hand boxer bank; confirm service-manual orientation.","Valvetrain noise or an oil-pressure warning requires stopping."],deepDive:[{heading:"Do not search for AVLS hardware on the wrong engine",paragraphs:["Decode the VIN and confirm the engine code before locating the pressure switch and solenoid. Forester model names span engines that do not share the same lift system.","Generic P0028 descriptions may resemble a VVT solenoid code. On the applicable Subaru system, the diagnostic relationship is ECM command, switching oil pressure and valve-lift feedback."]},{heading:"Test the circuit while it carries load",paragraphs:["Inspect oil contamination, terminal grip and harness routing, then test solenoid current and pressure-switch state. A cold resistance check may miss an intermittent hot connector.","Verify the specified oil and mechanical pressure before condemning electronics. Restricted oil galleries or unsuitable viscosity can prevent hydraulic switching even when the command circuit works."]},{heading:"Compare banks before opening the valvetrain",paragraphs:["Record both bank switch states at equal temperature and rpm. If Bank 1 changes correctly and Bank 2 does not, the comparison narrows electrical, hydraulic and mechanical possibilities.","Only inspect rocker/lift hardware after circuit and pressure evidence support it. Confirm correct state transition and no pending P0028 under the original enable conditions."]}],sources:[stis,owners]}),
 make(forester,{code:"P0011",slug:"subaru/forester/p0011",title:"P0011 Code Subaru Forester: Bank 1 AVCS Oil-Control Test",description:"Diagnose Forester P0011 with oil prerequisites, SSM cam data, right-bank control-valve and cam/crank correlation tests.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 1)",kind:"subaruVvt",quickAnswer:"P0011 means the applicable Forester's Bank 1 intake cam remained more advanced than commanded or failed the AVCS performance check. Subaru bulletin 02-132-12R provides a model-specific route for covered Forester FB engines, including SSM data and a controlled oil-control-valve comparison. Verify oil and pressure, test the right-hand intake valve and circuit, then scope cam/crank correlation. A bulletin procedure for FB engines should not be copied blindly to EJ turbo or later powertrains.",yearNotes:["02-132-12R lists covered Forester FB applications and model-specific verification.","Bank 1/right-hand terminology follows Subaru vehicle orientation.","Intake and exhaust oil-control valves must never be interchanged.","New O-ring and nylon backer ring are required in the published comparison."],deepDive:[{heading:"Start with requested versus actual right-bank angle",paragraphs:["Record both banks at idle, during command and near the fault's temperature/load. One-bank over-advance differs from both banks responding poorly to shared oil or voltage.","Check oil level, viscosity, filter and mechanical pressure before commanding AVCS. Sludge or restricted oil flow can make a good valve appear slow."]},{heading:"Follow the swap limitations exactly",paragraphs:["On covered engines Subaru's comparison is intake-to-intake or exhaust-to-exhaust, never intake-to-exhaust. Replace the one-time sealing components so the test does not introduce leakage.","If P0011 follows a properly moved valve, it supports that component. If it remains on Bank 1, test local wiring, passage, phaser and feedback rather than replacing the opposite valve."]},{heading:"Distinguish waveform dropout from phase error",paragraphs:["An intermittent cam signal favors sensor, connector or wiring. Clean cam/crank patterns with a stable angular offset and rattle favor hydraulic or mechanical timing inspection.","Run the Forester-specific drive cycle or inspection mode after repair. Correct right-bank tracking with no pending P0011 confirms the outcome."]}],sources:[camBulletin,stis,owners]}),
 make(forester,{code:"P0021",slug:"subaru/forester/p0021",title:"P0021 Code Subaru Forester: Bank 2 AVCS Timing Test",description:"Diagnose Forester P0021 with left-bank requested/actual angle, oil-control valve, wiring, pressure and correlation evidence.",definition:"Intake Camshaft Position Timing Over-Advanced/System Performance (Bank 2)",kind:"subaruVvt",quickAnswer:"P0021 means the applicable Forester's Bank 2 intake cam was more advanced than commanded or failed AVCS performance. In Subaru's covered FB diagnostic procedure, P0021 identifies the left-hand intake oil-control branch. Save both-bank SSM angles, verify the correct oil, filter and pressure, test the valve and circuit, and scope cam/crank feedback before mechanical timing work. Do not confuse P0021 AVCS cam phase with P0028 AVLS valve-lift control on an older EJ engine.",yearNotes:["Engine identification determines whether the published FB procedure applies.","Bank 2 is the left-hand intake branch in that covered procedure.","A two-bank fault raises shared oil and base-timing priority.","One-time seals are required if the bulletin's valve comparison is performed."],deepDive:[{heading:"A bank comparison is useful only when conditions match",paragraphs:["Graph left and right requested/actual timing at the same oil temperature, rpm and load. A left-only error supports local circuit, valve, passage, phaser or sensor diagnosis.","If P0011 and P0021 arrive together, inspect oil level and pressure, supply voltage, common grounds and base timing before assuming two independent valves failed."]},{heading:"Test electrical command and hydraulic result",paragraphs:["Measure valve current and loaded circuit voltage, then confirm actual cam movement. A valve may click without metering oil correctly, and a restricted passage can leave a good valve ineffective.","Use Subaru's controlled side-to-side procedure only on an applicable engine, with new seals and no intake/exhaust interchange. Preserve the result rather than repeatedly moving parts."]},{heading:"Correlation testing protects against unnecessary teardown",paragraphs:["Missing waveform edges indicate an electrical or sensor problem; a stable offset with clean signals and timing noise supports mechanical inspection. The DTC alone does not prove chain stretch.","Complete the correct verification route and confirm Bank 2 follows command with no pending P0021 under the original operating condition."]}],sources:[camBulletin,stis,owners]}),
 make(forester,{code:"P0457",slug:"subaru/forester/p0457",title:"P0457 Code Subaru Forester: Cap, Purge and EVAP Leak Test",description:"Diagnose Forester P0457 by recording fuel-cap condition and testing filler, purge, vent, canister, hose and tank sealing.",definition:"EVAP System Leak Detected (Fuel Cap Loose/Off)",kind:"evapCap",quickAnswer:"P0457 means the Forester EVAP system behaved as if a cap were loose/off or another significant opening prevented sealing. Preserve the cap and fuel-level evidence, inspect the seal and corrosion at the filler neck, test purge and vent operation, then use regulated EVAP smoke to locate hose, canister, tank or pump-seal leakage. Older underbody routing and newer leak-check modules differ, so use the correct STIS diagram. Do not treat a replacement cap as proof without a passing test.",yearNotes:["Filler neck corrosion and rear-underbody exposure matter on older Foresters.","Canister and leak-check components changed across SF, SG, SH, SJ and SK.","Hard starting after refueling raises purge-leak priority.","The EVAP monitor requires specific fuel level, temperature and soak."],deepDive:[{heading:"Record the filler condition before correcting it",paragraphs:["Note whether the cap was missing, cross-threaded or insufficiently tightened and inspect its gasket and the neck's sealing surface. Rust or dents can defeat a new cap.","If the cap was found loose and the sealed system passes the approved test, that is meaningful evidence. A returning P0457 requires complete system diagnosis."]},{heading:"Underbody exposure changes inspection priority",paragraphs:["Inspect vapor hoses, quick connections and canister mounting for road damage, corrosion and disturbance after fuel-pump or collision work. Do not infer leakage from dirt alone.","Command purge and vent components and verify actual sealing. Use only EVAP-safe regulated smoke, then section the filler, canister and tank branches to localize escape."]},{heading:"Readiness is part of the repair",paragraphs:["Record fuel level and soak conditions before clearing because EVAP may not rerun immediately. Avoid topping off the tank, which can contaminate the canister.","A passing leak check plus completed monitor and no pending P0457 confirms repair. A lamp that stays off while readiness is incomplete does not."]}],sources:[techTips,stis,owners]}),
 make(forester,{code:"P0172",slug:"subaru/forester/p0172",title:"P0172 Code Subaru Forester: Rich Fuel Correction Diagnosis",description:"Diagnose Forester P0172 through injector, fuel-pressure, purge, MAF, A/F sensor, intake and fuel-dilution tests.",definition:"System Too Rich (Bank 1)",kind:"rich",quickAnswer:"P0172 means the Forester ECM had to remove excessive fuel from Bank 1. Save correction and learning at idle, load and cold start; inspect labeled plugs and oil dilution; test purge sealing, injector leakage and fuel pressure; then validate MAF and upstream A/F data. EJ port injection, FB port injection and FA20DIT direct injection use different fuel procedures. Do not replace the A/F sensor simply because it reported the rich exhaust condition.",yearNotes:["FA20DIT high-pressure work requires Subaru's depressurization and safety procedure.","Turbo inlet and boost leaks can distort airflow calculations differently.","A rising oil level or strong gasoline odor indicates possible dilution.","Older calibration history is narrow and never substitutes for physical diagnosis."],deepDive:[{heading:"Use correction pattern to choose the first branch",paragraphs:["Richest correction at idle with difficult hot restarts raises a leaking injector or purge flow. Correction across idle and load raises pressure, MAF bias, intake restriction or shared feedback.","Keep plugs labeled. One fuel-wet cylinder supports a local injector or ignition problem more strongly than replacing a shared sensor."]},{heading:"Test fuel safely for the engine installed",paragraphs:["Check residual pressure, commanded pressure and injector contribution according to the engine family. A port-injected EJ procedure is unsafe and inaccurate when copied to FA20 direct injection.","Test purge closed-state sealing and record whether the symptom follows refueling. Excess vapor can make the mixture rich even when liquid-fuel pressure is normal."]},{heading:"Reconcile airflow, feedback and combustion",paragraphs:["Inspect the filter and inlet, compare MAF with calculated load, and check exhaust integrity before evaluating the upstream A/F sensor. Misfire can leave misleading oxygen and fuel patterns.","Correct the proven cause and address fuel-contaminated oil under the service procedure. Verify stable learning and no pending P0172 under the original condition."]}],sources:[techTips,stis,owners]}),
 make(forester,{code:"P0137",slug:"subaru/forester/p0137",title:"P0137 Code Subaru Forester: Rear O2 Circuit and Bulletin Test",description:"Diagnose Forester P0137 with exhaust, mixture, heater, circuit and exact Subaru rear-sensor or turbo-calibration applicability.",definition:"O2 Sensor Circuit Low Voltage (Bank 1, Sensor 2)",kind:"rearO2Low",quickAnswer:"P0137 means the Forester Bank 1 downstream oxygen-sensor signal stayed low. Check exhaust leakage, upstream mixture and misfire before load-testing rear-sensor signal, heater and harness. Subaru bulletin 09-115-24 covers identified 2019–2023 Forester applications with a rear-sensor design change. A separate bulletin 11-169-16R includes P0137 in a narrow 2014–2017 Forester turbo ECM branch and instructs technicians to eliminate improper fuel first. Neither bulletin applies from code wording alone.",yearNotes:["09-115-24 requires sensor identification on listed 2019–2023 Foresters.","11-169-16R is limited to specified 2014–2017 turbo ECM applications.","Naturally aspirated and turbo exhaust routing differs.","P0171, P0300 and P0420 companions change diagnostic priority."],deepDive:[{heading:"Two Subaru bulletins describe different branches",paragraphs:["The 2024 sensor bulletin concerns identified rear O2 sensor production on listed later models. The turbo ECM bulletin concerns particular 2014–2017 FA20DIT calibrations and requires checking fuel quality first.","Do not combine them into a universal Forester repair. VIN, engine, ECM part number and sensor identification determine whether either branch applies."]},{heading:"Prove whether low voltage is electrical or real",paragraphs:["Graph rear voltage, heater status, upstream A/F response and fuel correction after warm-up. A circuit pinned low with failed loaded tests differs from a responsive sensor seeing oxygen from a lean exhaust or leak.","Inspect connectors and harness near heat shields and underbody points, then inspect the exhaust cold for soot or cracks ahead of the sensor."]},{heading:"Clear upstream faults before catalyst conclusions",paragraphs:["Resolve P0171 or P0300 because mixture and misfire directly affect downstream oxygen. Subaru's P0420 diagnostic bulletin treats P0137 as a prerequisite code.","Verify the repair through the hot monitor with plausible sensor response and no pending P0137. A software update cannot seal an exhaust leak or repair a damaged circuit."]}],sources:[rearSensorBulletin,foresterTurboBulletin,catalystBulletin,stis,owners]}),
 make(forester,{code:"P2096",slug:"subaru/forester/p2096",title:"P2096 Code Subaru Forester: Post-Catalyst Lean Test",description:"Diagnose Forester P2096 with Subaru's corrected late-model procedure, upstream fuel control, exhaust and rear-sensor testing.",definition:"Post Catalyst Fuel Trim System Too Lean (Bank 1)",kind:"postCatLean",quickAnswer:"P2096 means the Forester's post-catalyst Bank 1 fuel correction reached a lean limit; it does not prove a rear sensor or converter failed. Save upstream learning, P0171/P0300/P0137/P0420 companions and rear-sensor data, inspect exhaust leaks, correct upstream fuel-control faults, then test the sensor and catalyst. Subaru bulletin 18-228-25 replaces specified service-manual diagnostic steps for listed 2019–2025 Foresters. It changes the diagnostic path rather than prescribing one replacement part.",yearNotes:["18-228-25 lists 2019–2025 Forester with year-specific replaced steps.","Earlier Foresters require the current STIS path for their exact engine.","Turbo exhaust layout and fueling require separate interpretation.","P2096 plus P0171 makes upstream lean diagnosis the priority."],deepDive:[{heading:"Post-catalyst correction still begins with combustion",paragraphs:["Review short- and long-term correction, roughness counts and upstream A/F response. A true lean mixture or repeated misfire reaches the rear sensor after passing through the converter.","Test intake sealing, MAF plausibility, purge and fuel delivery when upstream data is abnormal. Fixing a downstream sensor cannot correct a vacuum leak or weak pump."]},{heading:"Inspect every exhaust joint that can admit oxygen",paragraphs:["Check manifolds, turbo joints where applicable, flanges, welds, flex sections and sensor bungs cold. A small leak may leave soot without making a loud noise.","After exhaust integrity passes, load-test Bank 1 Sensor 2 signal, ground and heater. Compare its response with upstream data rather than labeling any low trace a failed sensor."]},{heading:"The 2025 bulletin is a diagnostic correction",paragraphs:["Bulletin 18-228-25 identifies exact numbered steps replaced for 2019–2024 and 2025 Foresters. It does not say all covered vehicles need the same sensor, ECM or catalyst.","Complete the prescribed monitor after the root cause is repaired. Normal upstream and post-catalyst data with no pending P2096 provide the final evidence."]}],sources:[p2096Bulletin,rearSensorBulletin,catalystBulletin,stis,owners]})
];
